import pathlib


def per_page(default=10):
    path = pathlib.Path.home() / ".config" / "pager" / "config.toml"
    if not path.exists():
        return default
    for line in path.read_text().splitlines():
        key, _, value = line.partition("=")
        if key.strip() == "per_page":
            return int(value)
    return default

